public static AudioOffloadSupport getOffloadedPlaybackSupport(AudioFormat audioFormat, android.media.AudioAttributes audioAttributes, boolean isOffloadVariableRateSupported) {
  int playbackOffloadSupport = AudioManager.getPlaybackOffloadSupport(audioFormat, audioAttributes);
  if (playbackOffloadSupport == AudioManager.PLAYBACK_OFFLOAD_NOT_SUPPORTED) {
    return AudioOffloadSupport.DEFAULT_UNSUPPORTED;
  }
  AudioOffloadSupport.Builder audioOffloadSupport = new AudioOffloadSupport.Builder();
  return audioOffloadSupport.setIsFormatSupported(true).setIsGaplessSupported(playbackOffloadSupport == AudioManager.PLAYBACK_OFFLOAD_GAPLESS_SUPPORTED).setIsSpeedChangeSupported(isOffloadVariableRateSupported).build();
}
